import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Perioden, Aktualisierung und Zeit","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/03.perioden-und-zeit.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","filePath":"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","lastUpdated":null}'),i={name:"de/adapter/sourceanalytix/hintergrund/perioden-und-zeit.md"};function d(s,e,o,h,u,c){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="perioden-aktualisierung-und-zeit" tabindex="-1">Perioden, Aktualisierung und Zeit <a class="header-anchor" href="#perioden-aktualisierung-und-zeit" aria-label="Permalink to &quot;Perioden, Aktualisierung und Zeit&quot;">​</a></h1><p><a id="values-updated-live-midnight"></a></p><h2 id="wann-werden-werte-aktualisiert-–-live-oder-um-mitternacht" tabindex="-1">Wann werden Werte aktualisiert – live oder um Mitternacht? <a class="header-anchor" href="#wann-werden-werte-aktualisiert-–-live-oder-um-mitternacht" aria-label="Permalink to &quot;Wann werden Werte aktualisiert – live oder um Mitternacht?&quot;">​</a></h2><p><strong>Kurz:</strong> Beides. Die laufenden Werte rechnet SourceAnalytix bei jedem neuen Wert der Quelle sofort neu. Um Mitternacht kommt der Periodenwechsel dazu: Dann schreibt es die Vorperioden wie „gestern“, setzt neue Startwerte und beginnt die neuen Perioden bei 0.</p><h3 id="was-wann-geschrieben-wird" tabindex="-1">Was wann geschrieben wird <a class="header-anchor" href="#was-wann-geschrieben-wird" aria-label="Permalink to &quot;Was wann geschrieben wird&quot;">​</a></h3><table tabindex="0"><thead><tr><th>States</th><th>Wann</th></tr></thead><tbody><tr><td><code>cumulativeReading</code> und unter <code>currentYear.&lt;Kategorie&gt;</code> die Werte <code>01_currentDay</code> bis <code>05_currentYear</code></td><td>bei jedem neuen Wert der Quelle, aber nur, wenn sich der Wert ändert</td></tr><tr><td><code>currentWeek.&lt;Wochentag&gt;</code>, <code>weeks</code>, <code>months</code>, <code>quarters</code> der laufenden Periode und das Jahresarchiv</td><td>ebenso bei jedem neuen Wert</td></tr><tr><td><code>statisticsJson</code></td><td>gesammelt kurz nach den Änderungen, höchstens alle 300 ms</td></tr><tr><td><code>01_previousDay</code> bis <code>05_previousYear</code></td><td>beim Wechsel der jeweiligen Periode, mit Zeitstempel 23:59:59 Uhr am letzten Tag der Periode</td></tr><tr><td>Startwerte in den Einstellungen der Quelle</td><td>beim Wechsel der jeweiligen Periode</td></tr></tbody></table><p>Alle Werte schreibt SourceAnalytix bestätigt (<code>ack=true</code>). Weil die laufenden Werte nur bei einer Änderung geschrieben werden, zeigt ihr Zeitstempel die letzte Änderung. Liefert die Quelle eine Zeit lang keinen neuen Wert, bleiben auch die Werte von SourceAnalytix stehen.</p><p>Bei Leistungsquellen (W) rechnet SourceAnalytix mit jedem neuen Leistungswert die Energie seit dem letzten Wert aus. Auch hier ändern sich die Werte also nur, wenn das Gerät etwas meldet.</p><h3 id="der-wechsel-um-mitternacht" tabindex="-1">Der Wechsel um Mitternacht <a class="header-anchor" href="#der-wechsel-um-mitternacht" aria-label="Permalink to &quot;Der Wechsel um Mitternacht&quot;">​</a></h3><p>Um 0:00 Uhr Systemzeit prüft SourceAnalytix, welche Perioden zu Ende sind: der Tag immer, die Woche am Montag, der Monat am 1., das Quartal am 1. Januar, April, Juli und Oktober, das Jahr am 1. Januar. Für jede beendete Periode kopiert es den laufenden Wert in die Vorperiode und setzt den Startwert auf den aktuellen Gesamtstand. Die neue Periode beginnt damit bei 0.</p><p>Am Montag leert SourceAnalytix außerdem die Wochentage der laufenden Woche, am 1. Januar die Wochen, Monate und Quartale unter <code>currentYear</code>.</p><p>Während des Wechsels pausiert die Berechnung kurz. Werte, die in diesem Moment eintreffen, werden nicht verarbeitet. Eine Änderung ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1270" target="_blank" rel="noreferrer">#1270</a>).</p><p>War ioBroker um Mitternacht aus, holt SourceAnalytix den Wechsel beim Start nach, außerdem prüft es jede Stunde. Siehe <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker war um Mitternacht aus</a>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Wo finde ich gestern, letzte Woche, letzten Monat?</a> · <a href="#week-month-quarter-year-values">Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte?</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Absturz oder Wechsel zur falschen Zeit</a></p><p><a id="week-52-53-have-values"></a></p><h2 id="warum-zeigt-woche-52-53-werte-im-neuen-jahr" tabindex="-1">Warum zeigt Woche 52/53 Werte im neuen Jahr? <a class="header-anchor" href="#warum-zeigt-woche-52-53-werte-im-neuen-jahr" aria-label="Permalink to &quot;Warum zeigt Woche 52/53 Werte im neuen Jahr?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix zählt Kalenderwochen nach ISO 8601. Eine Woche beginnt am Montag, und Woche 1 ist die Woche mit dem ersten Donnerstag des Jahres. Die ersten Tage im Januar können deshalb noch zu Woche 52 oder 53 des Vorjahres gehören, die letzten Tage im Dezember schon zu Woche 1 des nächsten Jahres.</p><p>Zwei Beispiele:</p><table tabindex="0"><thead><tr><th>Tage</th><th>Kalenderwoche</th></tr></thead><tbody><tr><td>Montag, 29. Dezember 2025, bis Sonntag, 4. Januar 2026</td><td>Woche 1 von 2026</td></tr><tr><td>Montag, 28. Dezember 2026, bis Sonntag, 3. Januar 2027</td><td>Woche 53 von 2026</td></tr></tbody></table><h3 id="wie-sourceanalytix-damit-umgeht" tabindex="-1">Wie SourceAnalytix damit umgeht <a class="header-anchor" href="#wie-sourceanalytix-damit-umgeht" aria-label="Permalink to &quot;Wie SourceAnalytix damit umgeht&quot;">​</a></h3><p><strong>Ab v0.6.2:</strong> SourceAnalytix ordnet jede Woche dem Jahr zu, zu dem sie nach ISO 8601 gehört (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1256" target="_blank" rel="noreferrer">#1256</a>). Im Einzelnen:</p><ul><li><strong><code>02_currentWeek</code></strong> zählt immer die ganze Woche von Montag bis Sonntag, auch über den Jahreswechsel. Am 2. Januar 2027 enthält sie also den Verbrauch seit Montag, 28. Dezember. <code>05_currentYear</code> beginnt dagegen am 1. Januar bei 0.</li><li><strong><code>currentYear.&lt;Kategorie&gt;.weeks</code></strong> zeigt nur Wochen, die zum laufenden Kalenderjahr gehören. Vom 1. bis 3. Januar 2027 schreibt SourceAnalytix dort nichts, denn Woche 53 gehört zu 2026. Ebenso schreibt es am 29. bis 31. Dezember 2025 nicht in Woche <code>01</code>, damit die erste Januarwoche des laufenden Jahres nicht überschrieben wird.</li><li><strong>Das Wochenarchiv</strong> <code>&lt;Jahr&gt;.&lt;Kategorie&gt;.weeks</code> liegt im Ordner des Jahres, zu dem die Woche gehört. Woche 53 von 2026 steht unter <code>2026.consumed.weeks.53</code>, auch mit den Januartagen von 2027. Woche 1 von 2026 steht unter <code>2026.consumed.weeks.01</code>, auch mit den Dezembertagen von 2025.</li></ul><p><strong>Bis v0.6.1:</strong> SourceAnalytix nahm für Wochen zwar die ISO-Nummer, aber das Kalenderjahr. Anfang Januar landeten die Werte von Woche 52 oder 53 deshalb unter <code>currentYear</code> und im Archivordner des neuen Jahres. Ende Dezember überschrieb Woche 1 des nächsten Jahres die erste Januarwoche im Archiv des laufenden Jahres.</p><p><strong>Siehe auch:</strong> <a href="#week-month-quarter-year-values">Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Welche States gibt es für Wochen, Monate und Wochentage?</a> · <a href="./../referenz/states-und-meldungen#happens-turn-year">Was passiert zum Jahreswechsel?</a></p><p><a id="sourceanalytix-calculate-retroactively-only-activation"></a></p><h2 id="berechnet-sourceanalytix-ruckwirkend-oder-erst-ab-aktivierung" tabindex="-1">Berechnet SourceAnalytix rückwirkend oder erst ab Aktivierung? <a class="header-anchor" href="#berechnet-sourceanalytix-ruckwirkend-oder-erst-ab-aktivierung" aria-label="Permalink to &quot;Berechnet SourceAnalytix rückwirkend oder erst ab Aktivierung?&quot;">​</a></h2><p><strong>Kurz:</strong> Erst ab der Aktivierung. SourceAnalytix rechnet keine Werte aus der Vergangenheit nach. Kennst du die Zählerstände zu Beginn der laufenden Perioden, kannst du sie als Startwerte eintragen. Dann zählt der Verbrauch seit Beginn des Tages, der Woche, des Monats, des Quartals oder des Jahres mit, aber nur für die laufenden Perioden.</p><h3 id="was-bei-der-ersten-aktivierung-passiert" tabindex="-1">Was bei der ersten Aktivierung passiert <a class="header-anchor" href="#was-bei-der-ersten-aktivierung-passiert" aria-label="Permalink to &quot;Was bei der ersten Aktivierung passiert&quot;">​</a></h3><p>Beim ersten Wert einer neuen Quelle setzt SourceAnalytix jeden leeren Startwert und jeden Startwert 0 auf den aktuellen Gesamtstand. Alle Perioden beginnen damit bei 0. Im Log steht „Initialized empty period start values for … from current reading …“. Startwerte, die du eingetragen hast, bleiben, wie sie sind.</p><p>Ab v0.7.0 fragt der Assistent „Quelle hinzufügen“ das im Schritt „Startwerte“ ab:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Was passiert</th></tr></thead><tbody><tr><td>„Ab jetzt zählen“</td><td>Alle Perioden beginnen jetzt bei 0.</td></tr><tr><td>„Verbrauch seit Periodenbeginn mitzählen“</td><td>Du trägst die Zählerstände zu Beginn von Tag, Woche, Monat, Quartal und Jahr ein. Leere Felder beginnen ab jetzt.</td></tr></tbody></table><p>Was genau in die Felder gehört, steht unter <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a>.</p><h3 id="was-danach-gilt" tabindex="-1">Was danach gilt <a class="header-anchor" href="#was-danach-gilt" aria-label="Permalink to &quot;Was danach gilt&quot;">​</a></h3><ul><li>Der erste Monat, das erste Quartal und das erste Jahr enthalten nur den Verbrauch seit der Aktivierung, außer du hast Startwerte eingetragen.</li><li>Die Vorperioden wie <code>01_previousDay</code> oder <code>03_previousMonth</code> sind erst nach dem ersten Wechsel der jeweiligen Periode gefüllt.</li><li>Für frühere Perioden, etwa das Vorjahr, kann SourceAnalytix keine Werte erzeugen. Startwerte wirken nur bis zum Ende der laufenden Periode.</li></ul><p>Leistungsquellen (W) zählen immer ab der Aktivierung. Sie liefern keinen Zählerstand, SourceAnalytix bildet ihren Gesamtstand erst ab der Aktivierung selbst. Der Assistent bietet „Verbrauch seit Periodenbeginn mitzählen“ bei ihnen deshalb nicht an.</p><p>Ältere Verbräuche oder abgelesene Zählerstände nachzutragen ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/256" target="_blank" rel="noreferrer">#256</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Warum sind meine Werte nach der Eingabe von Startwerten negativ?</a></p><p><a id="week-month-quarter-year-values"></a></p><h2 id="warum-unterscheiden-sich-wochen-monats-quartals-und-jahreswerte" tabindex="-1">Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte? <a class="header-anchor" href="#warum-unterscheiden-sich-wochen-monats-quartals-und-jahreswerte" aria-label="Permalink to &quot;Warum unterscheiden sich Wochen-, Monats-, Quartals- und Jahreswerte?&quot;">​</a></h2><p><strong>Kurz:</strong> Jede Periode hat ihren eigenen Startwert und beginnt zu einem anderen Zeitpunkt. Der Verbrauch ist immer Gesamtstand − Startwert dieser Periode. Weil eine Woche am Montag beginnt und über Monats- oder Jahresgrenzen reichen kann, passen Wochenwerte nicht zu Monats- oder Jahreswerten, und die Summe der Wochen ergibt nicht den Monat.</p><h3 id="wann-welche-periode-beginnt" tabindex="-1">Wann welche Periode beginnt <a class="header-anchor" href="#wann-welche-periode-beginnt" aria-label="Permalink to &quot;Wann welche Periode beginnt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Periode</th><th>State unter <code>currentYear.&lt;Kategorie&gt;</code></th><th>beginnt um 0:00 Uhr am</th></tr></thead><tbody><tr><td>Tag</td><td><code>01_currentDay</code></td><td>jedem Tag</td></tr><tr><td>Woche</td><td><code>02_currentWeek</code></td><td>Montag</td></tr><tr><td>Monat</td><td><code>03_currentMonth</code></td><td>1. des Monats</td></tr><tr><td>Quartal</td><td><code>04_currentQuarter</code></td><td>1. Januar, 1. April, 1. Juli, 1. Oktober</td></tr><tr><td>Jahr</td><td><code>05_currentYear</code></td><td>1. Januar</td></tr></tbody></table><p>Zum Wechsel setzt SourceAnalytix den Startwert jeder beendeten Periode auf den Gesamtstand in diesem Moment. Die anderen Perioden laufen unberührt weiter.</p><h3 id="warum-die-werte-nicht-zusammenpassen" tabindex="-1">Warum die Werte nicht zusammenpassen <a class="header-anchor" href="#warum-die-werte-nicht-zusammenpassen" aria-label="Permalink to &quot;Warum die Werte nicht zusammenpassen&quot;">​</a></h3><ul><li><strong>Woche über die Monatsgrenze:</strong> Am Samstag, 3. Oktober 2026, zählt <code>03_currentMonth</code> drei Tage, <code>02_currentWeek</code> aber fünf, denn die Woche hat am Montag, 28. September, begonnen. Sie enthält also Tage, die zum Vormonat gehören. Dasselbe gilt am Jahreswechsel, siehe <a href="#week-52-53-have-values">Woche 52/53</a>.</li><li><strong>Aktivierung mitten in einer Periode:</strong> Ohne eigene Startwerte beginnen alle Perioden bei der Aktivierung. Der erste Monat, das erste Quartal und das erste Jahr enthalten dann gleich viel, nämlich den Verbrauch seit der Aktivierung.</li><li><strong>Eigene Startwerte:</strong> Hast du Startwerte eingetragen, zählt jede Periode ab ihrem eigenen Wert. Passen die Werte nicht zueinander, passen auch die Ergebnisse nicht.</li><li><strong>Rundung:</strong> SourceAnalytix rundet jeden Periodenwert für sich. Die Summe gerundeter Tageswerte kann deshalb in der letzten Stelle vom Monatswert abweichen.</li></ul><p>Bei den Kosten kommt der Grundpreis dazu: Er wird monatlich gebucht und nicht gleichmäßig auf die Tage verteilt. Mehr dazu unter <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">Wie rechne ich einen monatlichen Grundpreis ein?</a>.</p><h3 id="wo-die-einzelnen-wochen-und-monate-stehen" tabindex="-1">Wo die einzelnen Wochen und Monate stehen <a class="header-anchor" href="#wo-die-einzelnen-wochen-und-monate-stehen" aria-label="Permalink to &quot;Wo die einzelnen Wochen und Monate stehen&quot;">​</a></h3><p>Die einzelnen Wochen, Monate und Quartale des laufenden Jahres findest du unter <code>currentYear.&lt;Kategorie&gt;.weeks.01</code> bis <code>53</code>, <code>months.01_January</code> bis <code>12_December</code> und <code>quarters.Q1</code> bis <code>Q4</code>, wenn in den Instanz-Einstellungen unter „Laufendes Jahr“ „Wochen“, „Monate“ und „Quartale“ an sind. Der Februar steht also in <code>months.02_February</code>.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Welche States gibt es für Wochen, Monate und Wochentage?</a> · <a href="#values-updated-live-midnight">Wann werden Werte aktualisiert?</a></p>',49)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
